        this.irisActivationSubscription?.unsubscribe();
        this.featureToggleSubscription?.unsubscribe();
    }

    /**
     * Switches the currently displayed suggestion.
     * Navigates to the next suggestion if {@code up} is true, otherwise to the previous one.
     * Does nothing if there is no current suggestion, no suggestions to navigate, the current
     * suggestion cannot be located, or the navigation would move beyond the available bounds.
     *
     * @param up whether to move to the next (true) or previous (false) suggestion
     */
    switchSuggestion(up: boolean): void {
        if (!this.suggestion || !this.suggestions) {
            return;
        }
        const currentIndex = this.suggestions.indexOf(this.suggestion);
        if (currentIndex === -1) {
            return;
        }
        if (up) {
            if (currentIndex >= this.suggestions.length - 1) {
                return;
            }
            const newIndex = currentIndex + 1;
            this.suggestion = this.suggestions[newIndex];
            this.updateArrowDisabled(newIndex);
        } else {
            if (currentIndex <= 0) {
                return;
            }
            const newIndex = currentIndex - 1;
            this.suggestion = this.suggestions[newIndex];
            this.updateArrowDisabled(newIndex);
        }
    }

    /**
     * Updates the disabled state of the navigation arrows based on the current index.
     * The down arrow is disabled at the first element, the up arrow at the last element.
     *
     * @param currentIndex the index of the currently displayed suggestion
     */
    private updateArrowDisabled(currentIndex: number): void {
        this.downDisabled = currentIndex === 0;
        this.upDisabled = currentIndex === this.suggestions.length - 1;
    }

